for (size_t i = start; i < end; i++) {
    Particle *pi = &particles[i];
    pi->force = glm::vec3(0);

    // Get cell position for current particle
    glm::ivec3 cell = getCell(pi, h);

    // Check all neighboring cells
    for (int x = -1; x <= 1; x++) {
        for (int y = -1; y <= 1; y++) {
            for (int z = -1; z <= 1; z++) {
                glm::ivec3 neighborCell = cell + glm::ivec3(x, y, z);
                uint32_t cellHash = getHash(neighborCell);

                // Iterate through particles in this cell
                uint32_t pjIndex = particleTable[cellHash];
                while (pjIndex != NO_PARTICLE && pjIndex < particleCount) {
                    Particle *pj = &particles[pjIndex];

                    // Skip self-interaction
                    if (pj == pi) {
                        pjIndex++;
                        continue;
                    }

                    // Calculate distance and direction
                    glm::vec3 r = pj->position - pi->position;
                    float dist = glm::length(r);
                    float dist2 = dist * dist;

                    // Skip if outside kernel radius
                    if (dist2 > h2) {
                        pjIndex++;
                        continue;
                    }

                    // Calculate pressure force
                    float pressureForceScale = -mass * (pi->pressure + pj->pressure) /
                                             (2.0f * pj->density) * spikyGrad;
                    pressureForceScale *= std::pow(h - dist, 2);
                    glm::vec3 pressureForce = pressureForceScale * r;

                    // Calculate viscosity force
                    glm::vec3 velocityDiff = pj->velocity - pi->velocity;
                    float viscosityForceScale = viscosity * mass *
                                               (velocityDiff / pj->density) *
                                               spikyLap * (h - dist);
                    glm::vec3 viscosityForce = viscosityForceScale;

                    // Accumulate forces
                    pi->force += pressureForce + viscosityForce;

                    // Move to next particle in this cell
                    pjIndex++;
                }
            }
        }
    }
}

